insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('phuket-thailand', '07A', 'Phuket & Phi Phi', 'Thailand', 'Limestone islands and warm seas', 'live', 'verified', 'mountainValley', 'Phuket — Thailand (Andaman Sea)', '{"tropical","diveglobal","liveaboard","romance","culinary","wellness","family","ultra","ocean"}', '{}', '{}', null, null, '{"currency":"THB","node_tier":"ANCHOR","dossier_tier":"ANCHOR","si_disregarded":[{"si":"culture","reason":"Old Town and Wat Chalong not sourced in this build"},{"si":"entertainment","reason":"not-sourced-in-this-build"},{"si":"safari","reason":"not-a-safari-node"},{"si":"river","reason":"not-a-river-node"}],"key_facts":["Mu Ko Similan National Park, established 1982, 11 islands, 70 km off Phang Nga province, is CLOSED 16 May to 15 October every year. Source: en.wikipedia.org/wiki/Similan_Islands, accessed 2026-08-23.","Maya Bay on Ko Phi Phi Le closed indefinitely on 1 October 2018 after roughly 5,000 visitors and 200 boats a day destroyed 80% of the surrounding coral; it reopened in early 2022 with no boats in the bay, no swimming and a one-hour limit. Source: en.wikipedia.org/wiki/Maya_Bay, accessed 2026-08-23.","Ao Phang Nga National Park was established in 1981 and the bay covers 400 km2; Ko Tapu (James Bond Island) sits 20 m off the beach at Khao Phing Kan and appeared in The Man with the Golden Gun (1974) and Tomorrow Never Dies (1997). Source: en.wikipedia.org/wiki/Phang_Nga_Bay, accessed 2026-08-23.","The FCDO advises against all but essential travel to Pattani, Yala and Narathiwat provinces, to the districts of Chana, Thepa, Na Thawi and Saba Yoi in southern Songkhla, and to within 20km of the land border with Cambodia. Phuket is in none of them. Source: gov.uk/foreign-travel-advice/thailand/regional-risks, read 2026-08-23.","SSS Recompression Chamber, Phuket is 24-hour and multiplace, established 1996, with the SSS Evacuation Center at Khao Lak on the Tap Lamu departure coast. Source: our own output/similan-islands-thailand.md, verified 2026-08-09.","Phuket high season is mid-December to mid-January with a 3-6 month booking lead; the green season runs May-November at 30-50% off - the same months the Similan park is shut. Source: our own output/VILLAS-SUPPLY-STAYWELL.md."],"timing":{"peak":"mid-Dec to mid-Jan","shoulder":"Apr-Jun; Sep-Oct","green":"May-Nov, 30-50% off","inflection":"Jul-Sep - the curve rises as the Similan reopening is announced and the northern winter books","fire_date":"late Jun / early Jul - 1-2 weeks before the ramp BEGINS, never before the peak","booking_lead":"3-6 months at high season","event_peaks":"Christmas / New Year; the Similan park reopening on 16 October","off_season_specials":"green-season villa rates 30-50% off May-Nov - but the dive park is closed 16 May to 15 October"},"booking":{"advisory_updated":"2026-08-23","advisory_source":"https://www.gov.uk/foreign-travel-advice/thailand","note":"FCDO is the authority. Thailand is AREA-RESTRICTED: against all but essential travel to Pattani, Yala, Narathiwat, four districts of southern Songkhla, and within 20km of the Cambodian land border. Phuket is in none of them. Books freely. Read 2026-08-23.","booking_hold":false},"safety":{"booking_hold":false,"authority":"FCDO","source":"https://www.gov.uk/foreign-travel-advice/thailand","read":"2026-08-23","notes_verbatim":["Take care when swimming off coastal areas, especially during monsoon season. People have drowned in strong riptides.","Jellyfish can swim close to the shore, particularly during the rainy season from May to October. Jellyfish stings can be fatal.","Drink spiking and drug-assisted sexual assault does happen in tourist areas around Thailand.","beware of bag-snatchers, especially on motorbikes","take care when travelling in open transport like tuk-tuks"],"hospital":"Bangkok Hospital Phuket; Siriroj (verify)","hyperbaric":"SSS Recompression Chamber, Phuket - 24h, multiplace, established 1996; SSS Evacuation Center, Khao Lak (24h) on the Tap Lamu departure coast. Confirm readiness with the operator or DAN.","emergency":"191 police / 1669 ambulance (verify)","fcdo":{"posture":"1","_posture_is_ours":"OUR classification of the FCDO''s page, never her booking posture. The FCDO publishes no level and we assign none."},"fcdo_zones":[{"name":"The Thailand–Cambodia border region","lvl":2,"note":"Risk of armed conflict. Thai authorities may set security exclusion zones with little notice; unexploded ordnance is a stated risk. US emergency services near the border are limited."},{"name":"Yala, Pattani and Narathiwat provinces","lvl":2,"note":"Risk of unrest."}]},"geo":null,"seo":{"canonical":"/destination/phuket-thailand","keywords":["similan park open dates","maya bay rules 2026","phuket recompression chamber","phang nga james bond island","phuket green season villa"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":null,"last_verified_basis":"unprovable — no source_verified date and no FCDO read stamp"},"meta_title":"Phuket & Phi Phi, Thailand — TravelWell.World","meta_description":"Limestone islands and warm seas — when the Similan park is actually open, the rules that reopened Maya Bay, what the Foreign Office says, and why the villas are half price in the wrong months."},"jewels":[{"name":"Maya Bay, Ko Phi Phi Le","si":"tropical","si_tag":"Tropical Islands","when":"year-round","timing":"year-round","hook":"closed 1 Oct 2018 after ~5,000 visitors and ~200 boats a day destroyed 80% of the surrounding coral; reopened 2022 under no boats, no swimming, one hour","blurb":"closed 1 Oct 2018 after ~5,000 visitors and ~200 boats a day destroyed 80% of the surrounding coral; reopened 2022 under no boats, no swimming, one hour","commission":"operator","draw_ran