["liveaboard"],"shelf_fit":{"adventure":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tubbataha liveaboard week (mid-Mar-mid-Jun)","si_tag":"liveaboard","status":"live","tier":"premier","hook":"two-atoll + Jessie Beazley arc, park-season only","bookable_category":"liveaboard week (held)","source":"https://masterliveaboards.com/philippines/tubbataha-national-park/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","blurb":"two-atoll + Jessie Beazley arc, park-season only","when":"mid-Mar to mid-Jun","commission":"held","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["liveaboard"],"shelf_fit":{"adventure":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tubbataha Reefs UNESCO World Heritage marine park","si_tag":"globaladv","status":"future","tier":"premier","hook":"one of the planet''s recorded marine-biodiversity peaks; ranger-protected","bookable_category":"content / expedition (held)","source":"https://dan.org/alert-diver/article/tubbataha/","timing":"mid-Mar to mid-Jun","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"one of the planet''s recorded marine-biodiversity peaks; ranger-protected","when":"mid-Mar to mid-Jun","commission":"held","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["adventure"],"shelf_fit":{"adventure":"primary","liveaboard":"destination","ocean":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What is the current advisory for Tubbataha, and why is it not bookable here?","a":"'' The UK FCDO (reissued 1 April 2026) advises against all travel to western and central Mindanao and the Sulu archipelago. Tubbataha sits in the Sulu Sea, administratively Cagayancillo, Palawan, roughly 150 km southeast of Puerto Princesa. no park-authority, UNESCO or operator source resolves it either.","source":"https://www.gov.uk/foreign-travel-advice/philippines","si_tag":"safety"},{"q":"Is there a recompression chamber, and how remote is care?","a":"Care is remote and the sources disagree, so treat this as not verifiable as of 2026-08-10. Some operators cite a chamber at the city hospital in Puerto Princesa, Palawan, roughly 10-12 hours away by boat; one dive guide names Cebu City instead; and Master Liveaboards lists facilities at Batangas, Manila, Cebu and Subic reached by private air evacuation, without naming Puerto Princesa. No source confirms a 24-hour operational status. DAN membership and dive-accident insurance with air-evacuation cover are essential.","source":"tubbataha.ph + philippinedives.com + divehappy.com + masterliveaboards.com/faq/philippines (accessed 2026-08-10)","si_tag":"safety"},{"q":"When can I dive Tubbataha?","a":"Only in the mid-March to mid-June window, when park authorities open the season for the calmest weather; exact dates are set each year by the Tubbataha Management Office. It is liveaboard-only - no shore access and no night diving - with boats running from Puerto Princesa.","source":"dan.org/alert-diver/article/tubbataha + tubbataha.ph + masterliveaboards.com/philippines/tubbataha-national-park (accessed 2026-08-10)","si_tag":"planning"},{"q":"What will I see underwater?","a":"The park is recorded at hundreds of coral and fish species; grey reef sharks appear on nearly every dive, typically in groups, alongside whitetips and - depending on the day - hammerheads, thresher and whale sharks, mantas, and nesting hawksbill and green turtles.","source":"philippinedives.com/dive-guide/tubbataha + dan.org/alert-diver/article/tubbataha + masterliveaboards.com (accessed 2026-08-10)","si_tag":"liveaboard"},{"q":"Which sites define a Tubbataha week?","a":"Shark Airport for the grey-reef aggregation, the Delsan and Malayan wrecks, the walls at Black Rock, Southwest Wall and the North and South Atolls, Staghorn Point and Ko-ok, and the isolated Jessie Beazley Reef to the north.","source":"dan.org/alert-diver/article/tubbataha + philippinedives.com/dive-guide/tubbataha (accessed 2026-08-10)","si_tag":"liveaboard"},{"q":"What conditions and certification should I plan for?","a":"The atoll walls and Jessie Beazley are current-swept blue-water dives suited to experienced divers; sheltered reef tops suit a wider range with a guide. Nitrox is standard on the liveaboards. Dive within your certification and the operator briefing.","source":"masterliveaboards.com/philippines/tubbataha-national-park (accessed 2026-08-10)","si_tag":"liveaboard"}],"seo":{"meta_title":"Tubbataha Reefs Diving, Philippines: Season & Safety","meta_description":"Tubbataha Reefs, a UNESCO Sulu Sea liveaboard reef - the mid-March to mid-June season, the atoll walls and sharks, operators, and why booking is currently held.","slug":"tubbataha-philippines","primary_keyword":"Tubbataha Reefs liveaboard diving","long_tail":["Tubbataha dive season","Shark Airport Tubbataha","Tubbataha liveaboard","Sulu Sea advisory","Jessie Beazley Reef"],"search_language":"en","local_keywords":["Tubbataha Reefs","Sulu Sea diving"],"hreflang":["en"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-10","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-10","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/philippines","read":"2026-08-20T14:49:05Z","source_updated":"2026-07-15T09:55:25+01:00"}]}},"booking":{"booking_hold":true,"codes":[],"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-08-10","hits":3,"misses":19,"disregarded":3,"note":"Liveaboard-diving scope, held content-only; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"liveaboard","name":"liveaboard","status":"live"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"ocean","name":"ocean","status":"future"}],"ultra":[{"name":"HELD - private full-boat Philippine Siren / Philippines Aggressor charter across both atolls + Jessie Beazley + Palawan/El Nido land stay","why_ultra":"would be the ultra pull once the advisory boundary is resolved; not offered while content-only","earning":"held Aggressor reseller line - not booked while held","virtuoso_value_add":"n/a while held","mor":"n/a while held","source":"handoff/LIVEABOARD-OPERATOR-GRID-2026-08-09.md"}],"source_verified":"2026-08-10","hero":{"query":"Tubbataha Reefs, Philippines"},"geo":{"lat":8.85,"lng":119.92},"orbit":[],"orbit_country":[]}'::jsonb, 10),
  ('upper-mekong-laos', '07A', 'The Upper Mekong, Laos', 'Laos', 'The Mekong''s quiet crown', 'live', 'verified', 'venice', 'Southeast Asia', '{"river","culture","deepdive","culinary","adventure","romance","senior"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Upper Mekong Huay Xai<->Luang Prabang on LOW-DRAFT boutique boats (Heritage Line Anouvong 4-day ~$1,939pp, Pandaw, Luang Say, Nagi of Mekong) - big VN/KH lines can''t run this reach","Luang Prabang - UNESCO World Heritage town (1995): gilded wats (Wat Xieng Thong), French-colonial streets, dawn Tak Bat alms","Pak Ou Caves - ~4,000 Buddha images in two river caverns; Pak Beng overnight; Golden Triangle at Huay Xai; Kuang Si Falls near LP","SAFETY-SPINE: UXO (Indochina War) - advisory NAMES Luang Prabang + Vientiane - stay on well-used paths, never touch unknown metal","Landlocked (SE Asia''s only); currency Lao kip (LAK), USD/THB accepted; medevac to Thailand for serious cases"],"safety":{"emergency":"191 police / 190 fire / 195 ambulance (Laos lines; rural response limited)","hospital":"Luang Prabang + Vientiane basic; serious cases medevac to Thailand (Udon Thani/Bangkok) - air-medevac insurance advised","malaria":"low in Luang Prabang/river corridor (mosquito precautions; dengue present)","yellow_fever":"not required unless from endemic country","activity_note":"UXO safety-spine - stay on well-used roads/tracks/paths, never touch unknown metal (advisory names Luang Prabang + Vientiane); Mekong fast + low-draft water-dependent stretches (life vest, follow crew); Tak Bat observed silently at distance; hot/humid; dengue; rural care limited","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/laos","read":"2026-08-20T14:47:54Z","page_updated":"2026-08-13T12:10:25+01:00","source_country":"laos","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-free